{
  "tur": "cevap",
  "cevap": [
    {
      "alinti": {
        "kaynak_no": 1,
        "metin": "Problem: 1 | Problem: Upper thread is not tight. 0573M | Possible cause: ・ Is the upper thread tension too weak? Is the lower thread tension too strong? Adjust the lower thread tension or upper thread tension. Try pressing the special locus key and selecting No. 1."
      },
      "metin": "Üst iplik gergin değilse (Problem: 1 | 0573M), üst iplik gerginliği çok zayıf veya alt iplik gerginliği çok güçlü olabilir; alt iplik gerginliğini veya üst iplik gerginliğini ayarlayın. Özel locus tuşuna basmayı ve No. 1'i seçmeyi deneyin."
    },
    {
      "alinti": {
        "kaynak_no": 3,
        "metin": "Check that the upper threads have been threaded correctly. (Refer to \"4-5. Threading the upper thread\".)"
      },
      "metin": "Üst ipliklerin doğru şekilde takıldığını kontrol edin."
    },
    {
      "alinti": {
        "kaynak_no": 4,
        "metin": "After the lower thread tension has been adjusted, adjust the upper thread tension so that a good, even stitch is obtained. Lower the presser foot. Adjust by turning the tension nut (2)."
      },
      "metin": "Alt iplik gerginliği ayarlandıktan sonra, iyi ve düzgün bir dikiş elde etmek için üst iplik gerginliğini ayarlayın. Baskı ayağını (presser foot) indirin. Gerginlik somununu (tension nut) (2) çevirerek ayarlayın."
    }
  ],
  "sesli_metin": "Üst iplik gergin değilse üst veya alt iplik gerginliğini ayarlayın, özel locus tuşundan No. 1 seçeneğini deneyin, ipliklerin doğru takıldığını kontrol edin ve baskı ayağı aşağıdayken gerginlik somununu (2) çevirerek ayarlama yapın.",
  "celiski_var": false,
  "netlestirme_soru": null,
